import logging
import os
from datetime import datetime, timedelta, timezone
from functools import wraps
from pathlib import Path
from threading import RLock

import jwt
from flask import Flask, g, jsonify, request
from jwt import InvalidTokenError

from notification_tasks import send_notification_email
from repositories import TaskRepository, UserRepository


app = Flask(__name__)
logger = logging.getLogger(__name__)
app.config.update(
    DATA_FILE=os.environ.get("TASKS_FILE", "tasks.json"),
    USER_DATA_FILE=os.environ.get("USERS_FILE"),
    JWT_SECRET=os.environ.get("JWT_SECRET", os.urandom(32).hex()),
    JWT_EXPIRATION_SECONDS=3600,
)

_storage_lock = RLock()


def _data_file() -> Path:
    return Path(app.config["DATA_FILE"])


def _users_file() -> Path:
    configured = app.config.get("USER_DATA_FILE")
    if configured:
        return Path(configured)
    task_file = _data_file()
    return task_file.with_name(f"{task_file.stem}.users.json")


task_repository = TaskRepository(_data_file, _storage_lock)
user_repository = UserRepository(_users_file, _storage_lock)


def init_storage() -> None:
    """Create stores and migrate tasks written before ownership was added."""
    task_repository.initialize()
    user_repository.initialize()


@app.before_request
def ensure_storage_initialized() -> None:
    init_storage()


def _issue_token(user_id: int) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": str(user_id),
        "iat": now,
        "exp": now + timedelta(seconds=app.config["JWT_EXPIRATION_SECONDS"]),
    }
    return jwt.encode(payload, app.config["JWT_SECRET"], algorithm="HS256")


def require_auth(view):
    @wraps(view)
    def authenticated_view(*args, **kwargs):
        authorization = request.headers.get("Authorization", "")
        scheme, _, token = authorization.partition(" ")
        if scheme.lower() != "bearer" or not token:
            return jsonify({"error": "authentication required"}), 401
        try:
            payload = jwt.decode(
                token, app.config["JWT_SECRET"], algorithms=["HS256"]
            )
            user_id = int(payload["sub"])
        except (InvalidTokenError, KeyError, TypeError, ValueError):
            return jsonify({"error": "invalid token"}), 401

        if user_repository.get_by_id(user_id) is None:
            return jsonify({"error": "invalid token"}), 401
        g.user_id = user_id
        return view(*args, **kwargs)

    return authenticated_view


def _json_body() -> dict | None:
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else None


def _credentials() -> tuple[str, str] | None:
    data = _json_body()
    if data is None:
        return None
    username = data.get("username")
    password = data.get("password")
    if (
        not isinstance(username, str)
        or not username.strip()
        or not isinstance(password, str)
        or not password
    ):
        return None
    return username.strip(), password


@app.post("/auth/register")
def register():
    credentials = _credentials()
    if credentials is None:
        return jsonify({"error": "username and password are required"}), 400
    username, password = credentials
    user = user_repository.create_user(username, password)
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify({"id": user["id"], "username": user["username"]}), 201


@app.post("/auth/login")
def login():
    credentials = _credentials()
    if credentials is None:
        return jsonify({"error": "username and password are required"}), 400
    user = user_repository.authenticate(*credentials)
    if user is None:
        return jsonify({"error": "invalid username or password"}), 401
    return jsonify({"token": _issue_token(user["id"])})


@app.get("/tasks")
@require_auth
def list_tasks():
    return jsonify(task_repository.list_for_owner(g.user_id))


@app.post("/tasks")
@require_auth
def add_task():
    data = _json_body()
    title = data.get("title") if data is not None else None
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    return jsonify(task_repository.create_for_owner(title.strip(), g.user_id)), 201


@app.get("/tasks/<int:task_id>")
@require_auth
def show_task(task_id: int):
    task = task_repository.get_for_owner(task_id, g.user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.put("/tasks/<int:task_id>")
@require_auth
def edit_task(task_id: int):
    existing_task = task_repository.get_for_owner(task_id, g.user_id)
    if existing_task is None:
        return jsonify({"error": "task not found"}), 404

    data = _json_body()
    if data is None:
        return jsonify({"error": "JSON object is required"}), 400
    if "title" in data and (
        not isinstance(data["title"], str) or not data["title"].strip()
    ):
        return jsonify({"error": "title must be a non-empty string"}), 400
    if "status" in data and not isinstance(data["status"], str):
        return jsonify({"error": "status must be a string"}), 400

    title = data["title"].strip() if "title" in data else None
    task = task_repository.update_for_owner(
        task_id, g.user_id, title=title, status=data.get("status")
    )
    if existing_task["status"] != "completed" and task["status"] == "completed":
        owner = user_repository.get_by_id(g.user_id)
        try:
            send_notification_email.delay(owner["username"], task["title"])
        except Exception:
            logger.exception("Could not queue completion notification for task %s", task_id)
    return jsonify(task)


@app.errorhandler(404)
def route_not_found(_error):
    return jsonify({"error": "not found"}), 404


init_storage()


if __name__ == "__main__":
    app.run(debug=True)

from __future__ import annotations

import json
import os
import tempfile
from abc import ABC, abstractmethod
from collections.abc import Callable, Mapping
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any

from werkzeug.security import check_password_hash, generate_password_hash


class BaseRepository(ABC):
    """File-backed repository with atomic, shared CRUD operations."""

    def __init__(
        self,
        path_provider: Callable[[], Path],
        storage_name: str,
        lock: RLock | None = None,
    ) -> None:
        self._path_provider = path_provider
        self._storage_name = storage_name
        self._lock = lock or RLock()

    @property
    def path(self) -> Path:
        return self._path_provider()

    def initialize(self) -> None:
        with self._lock:
            if not self.path.exists():
                self._write([])

    def get_all(self) -> list[dict[str, Any]]:
        with self._lock:
            self.initialize()
            return self._read()

    def get_by_id(self, record_id: int) -> dict[str, Any] | None:
        return next(
            (record for record in self.get_all() if record["id"] == record_id),
            None,
        )

    def create(self, values: Mapping[str, Any]) -> dict[str, Any]:
        with self._lock:
            self.initialize()
            records = self._read()
            record = {
                "id": max((record["id"] for record in records), default=0) + 1,
                **self._build_record(values),
            }
            records.append(record)
            self._write(records)
            return record

    def update(
        self, record_id: int, values: Mapping[str, Any]
    ) -> dict[str, Any] | None:
        with self._lock:
            self.initialize()
            records = self._read()
            record = next(
                (record for record in records if record["id"] == record_id), None
            )
            if record is None:
                return None
            record.update(values)
            self._write(records)
            return record

    def delete(self, record_id: int) -> bool:
        with self._lock:
            self.initialize()
            records = self._read()
            remaining = [record for record in records if record["id"] != record_id]
            if len(remaining) == len(records):
                return False
            self._write(remaining)
            return True

    @abstractmethod
    def _build_record(self, values: Mapping[str, Any]) -> dict[str, Any]:
        """Build storage fields for a newly created record."""

    def _read(self) -> list[dict[str, Any]]:
        try:
            with self.path.open(encoding="utf-8") as store:
                data = json.load(store)
        except (json.JSONDecodeError, OSError) as exc:
            raise RuntimeError(f"{self._storage_name} storage is unreadable") from exc
        if not isinstance(data, list):
            raise RuntimeError(f"{self._storage_name} storage is invalid")
        return data

    def _write(self, records: list[dict[str, Any]]) -> None:
        path = self.path
        path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary_name = tempfile.mkstemp(
            dir=path.parent, prefix=f".{path.name}."
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as store:
                json.dump(records, store, indent=2)
                store.write("\n")
            os.replace(temporary_name, path)
        except BaseException:
            try:
                os.unlink(temporary_name)
            except FileNotFoundError:
                pass
            raise


class TaskRepository(BaseRepository):
    def __init__(
        self, path_provider: Callable[[], Path], lock: RLock | None = None
    ) -> None:
        super().__init__(path_provider, "task", lock)

    def initialize(self) -> None:
        with self._lock:
            super().initialize()
            tasks = self._read()
            migrated = False
            for task in tasks:
                if isinstance(task, dict) and "owner_id" not in task:
                    task["owner_id"] = None
                    migrated = True
            if migrated:
                self._write(tasks)

    def _build_record(self, values: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "title": values["title"],
            "status": "pending",
            "created_at": datetime.now(timezone.utc).isoformat(),
            "owner_id": values["owner_id"],
        }

    def create_for_owner(self, title: str, owner_id: int) -> dict[str, Any]:
        return self.create({"title": title, "owner_id": owner_id})

    def list_for_owner(self, owner_id: int) -> list[dict[str, Any]]:
        tasks = [
            task for task in self.get_all() if task.get("owner_id") == owner_id
        ]
        return sorted(tasks, key=lambda task: task["created_at"], reverse=True)

    def get_for_owner(
        self, task_id: int, owner_id: int
    ) -> dict[str, Any] | None:
        return next(
            (
                task
                for task in self.get_all()
                if task["id"] == task_id and task.get("owner_id") == owner_id
            ),
            None,
        )

    def update_for_owner(
        self,
        task_id: int,
        owner_id: int,
        *,
        title: str | None = None,
        status: str | None = None,
    ) -> dict[str, Any] | None:
        with self._lock:
            self.initialize()
            tasks = self._read()
            task = next(
                (
                    task
                    for task in tasks
                    if task["id"] == task_id and task.get("owner_id") == owner_id
                ),
                None,
            )
            if task is None:
                return None
            if title is not None:
                task["title"] = title
            if status is not None:
                task["status"] = status
            self._write(tasks)
            return task


class UserRepository(BaseRepository):
    def __init__(
        self, path_provider: Callable[[], Path], lock: RLock | None = None
    ) -> None:
        super().__init__(path_provider, "user", lock)

    def _build_record(self, values: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "username": values["username"],
            "password_hash": generate_password_hash(
                values["password"], method="scrypt"
            ),
        }

    def create_user(self, username: str, password: str) -> dict[str, Any] | None:
        with self._lock:
            self.initialize()
            if any(user["username"] == username for user in self._read()):
                return None
            return self.create({"username": username, "password": password})

    def authenticate(self, username: str, password: str) -> dict[str, Any] | None:
        user = next(
            (user for user in self.get_all() if user["username"] == username), None
        )
        if user is None or not check_password_hash(user["password_hash"], password):
            return None
        return user

import json
from unittest.mock import patch

import pytest

from app import app


@pytest.fixture
def client(tmp_path):
    app.config.update(
        TESTING=True,
        DATA_FILE=str(tmp_path / "tasks.json"),
        USER_DATA_FILE=None,
        JWT_SECRET="test-secret-that-is-at-least-32-bytes-long",
        JWT_EXPIRATION_SECONDS=3600,
    )
    return app.test_client()


def register(client, username="alice", password="secret"):
    return client.post(
        "/auth/register", json={"username": username, "password": password}
    )


def auth_headers(client, username="alice", password="secret"):
    if register(client, username, password).status_code not in (201, 409):
        raise AssertionError("could not register test user")
    response = client.post(
        "/auth/login", json={"username": username, "password": password}
    )
    return {"Authorization": f"Bearer {response.get_json()['token']}"}


def test_register_and_login(client):
    response = register(client)

    assert response.status_code == 201
    assert response.get_json() == {"id": 1, "username": "alice"}

    response = client.post(
        "/auth/login", json={"username": "alice", "password": "secret"}
    )
    assert response.status_code == 200
    assert isinstance(response.get_json()["token"], str)


def test_password_is_hashed(client):
    register(client, password="plain-password")

    with open(app.config["DATA_FILE"].replace("tasks.json", "tasks.users.json"), encoding="utf-8") as store:
        users = json.load(store)

    assert users[0]["password_hash"] != "plain-password"
    assert "password" not in users[0]


@pytest.mark.parametrize(
    "payload",
    [{}, {"username": "alice"}, {"password": "secret"}, {"username": " ", "password": "secret"}],
)
def test_register_requires_username_and_password(client, payload):
    response = client.post("/auth/register", json=payload)

    assert response.status_code == 400
    assert response.get_json() == {"error": "username and password are required"}


def test_duplicate_username_is_rejected(client):
    assert register(client).status_code == 201
    response = register(client, password="different")

    assert response.status_code == 409
    assert client.post(
        "/auth/login", json={"username": "alice", "password": "secret"}
    ).status_code == 200


def test_login_rejects_invalid_credentials(client):
    register(client)

    response = client.post(
        "/auth/login", json={"username": "alice", "password": "wrong"}
    )
    assert response.status_code == 401
    assert client.post(
        "/auth/login", json={"username": "missing", "password": "secret"}
    ).status_code == 401


@pytest.mark.parametrize(
    "headers",
    [None, {"Authorization": "Bearer invalid"}, {"Authorization": "Basic abc"}],
)
def test_tasks_require_valid_jwt(client, headers):
    kwargs = {"headers": headers} if headers else {}

    assert client.get("/tasks", **kwargs).status_code == 401
    assert client.post("/tasks", json={"title": "No"}, **kwargs).status_code == 401
    assert client.get("/tasks/1", **kwargs).status_code == 401
    assert client.put("/tasks/1", json={"status": "done"}, **kwargs).status_code == 401


def test_create_and_get_task(client):
    headers = auth_headers(client)
    response = client.post("/tasks", json={"title": "Write tests"}, headers=headers)

    assert response.status_code == 201
    assert response.get_json()["status"] == "pending"
    assert response.get_json()["owner_id"] == 1
    task_id = response.get_json()["id"]
    response = client.get(f"/tasks/{task_id}", headers=headers)
    assert response.get_json()["title"] == "Write tests"


def test_create_requires_title(client):
    headers = auth_headers(client)
    assert client.post("/tasks", json={}, headers=headers).status_code == 400
    assert client.post(
        "/tasks", json={"title": "  "}, headers=headers
    ).get_json() == {"error": "title is required"}


def test_list_is_newest_first(client):
    headers = auth_headers(client)
    first = client.post("/tasks", json={"title": "First"}, headers=headers).get_json()
    second = client.post("/tasks", json={"title": "Second"}, headers=headers).get_json()

    tasks = client.get("/tasks", headers=headers).get_json()
    assert [task["id"] for task in tasks] == [second["id"], first["id"]]


def test_update_title_and_status(client):
    headers = auth_headers(client)
    task = client.post("/tasks", json={"title": "Old"}, headers=headers).get_json()

    response = client.put(
        f"/tasks/{task['id']}",
        json={"title": "New", "status": "done"},
        headers=headers,
    )

    assert response.status_code == 200
    assert response.get_json()["title"] == "New"
    assert response.get_json()["status"] == "done"


def test_completing_task_queues_owner_notification(client):
    headers = auth_headers(client, username="alice@example.com")
    task = client.post(
        "/tasks", json={"title": "Ship release"}, headers=headers
    ).get_json()

    with patch("app.send_notification_email.delay") as delay:
        response = client.put(
            f"/tasks/{task['id']}",
            json={"status": "completed"},
            headers=headers,
        )

    assert response.status_code == 200
    delay.assert_called_once_with("alice@example.com", "Ship release")


def test_notification_is_only_queued_on_transition_to_completed(client):
    headers = auth_headers(client)
    task = client.post("/tasks", json={"title": "One time"}, headers=headers).get_json()

    with patch("app.send_notification_email.delay") as delay:
        client.put(
            f"/tasks/{task['id']}",
            json={"status": "completed"},
            headers=headers,
        )
        client.put(
            f"/tasks/{task['id']}", json={"title": "Renamed"}, headers=headers
        )
        client.put(
            f"/tasks/{task['id']}",
            json={"status": "completed"},
            headers=headers,
        )

    delay.assert_called_once_with("alice", "One time")


def test_missing_tasks_return_json_404(client):
    headers = auth_headers(client)
    assert client.get("/tasks/999", headers=headers).get_json() == {
        "error": "task not found"
    }
    response = client.put(
        "/tasks/999", json={"status": "done"}, headers=headers
    )
    assert response.status_code == 404
    assert response.get_json() == {"error": "task not found"}


def test_tasks_are_persisted_as_json(client):
    headers = auth_headers(client)
    client.post("/tasks", json={"title": "Persist me"}, headers=headers)

    with open(app.config["DATA_FILE"], encoding="utf-8") as store:
        tasks = json.load(store)

    assert tasks[0]["title"] == "Persist me"
    assert tasks[0]["owner_id"] == 1


def test_update_rejects_invalid_fields(client):
    headers = auth_headers(client)
    task = client.post("/tasks", json={"title": "Valid"}, headers=headers).get_json()

    assert client.put(
        f"/tasks/{task['id']}", json={"title": ""}, headers=headers
    ).status_code == 400
    assert client.put(
        f"/tasks/{task['id']}", json={"status": 1}, headers=headers
    ).status_code == 400


def test_users_only_see_and_update_their_own_tasks(client):
    alice_headers = auth_headers(client, "alice")
    alice_task = client.post(
        "/tasks", json={"title": "Alice task"}, headers=alice_headers
    ).get_json()
    bob_headers = auth_headers(client, "bob")
    bob_task = client.post(
        "/tasks", json={"title": "Bob task"}, headers=bob_headers
    ).get_json()

    assert client.get("/tasks", headers=alice_headers).get_json() == [alice_task]
    assert client.get("/tasks", headers=bob_headers).get_json() == [bob_task]
    assert client.get(
        f"/tasks/{alice_task['id']}", headers=bob_headers
    ).status_code == 404
    assert client.put(
        f"/tasks/{alice_task['id']}",
        json={"status": "done"},
        headers=bob_headers,
    ).status_code == 404


def test_legacy_tasks_are_migrated_without_data_loss(client):
    legacy_task = {
        "id": 7,
        "title": "Legacy",
        "status": "pending",
        "created_at": "2024-01-01T00:00:00+00:00",
    }
    with open(app.config["DATA_FILE"], "w", encoding="utf-8") as store:
        json.dump([legacy_task], store)

    headers = auth_headers(client)

    with open(app.config["DATA_FILE"], encoding="utf-8") as store:
        migrated_tasks = json.load(store)
    assert migrated_tasks == [{**legacy_task, "owner_id": None}]
    assert client.get("/tasks", headers=headers).get_json() == []

    new_task = client.post(
        "/tasks", json={"title": "New"}, headers=headers
    ).get_json()
    assert new_task["id"] == 8

